[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #000000;
      --green: #55DA9B;
      --purple: #5620C1;
      --white: #FFFFFF;
      --off-white: #F7F7F5;
      --light-gray: #F0F0ED;
      --mid-gray: #E5E5E0;
      --text-muted: #6B6B6B;
      --text-dark: #1A1A1A;
      --card-bg: #FFFFFF;
      --border: #E8E8E3;
      --font: 'Plus Jakarta Sans', sans-serif;
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --radius-full: 999px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--white);
      color: var(--text-dark);
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ─── NAV ─── */
    nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      padding: 0 40px;
      height: 68px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .nav-logo {
      font-size: 22px;
      font-weight: 800;
      letter-spacing: -0.5px;
      color: var(--black);
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .nav-logo-dot {
      width: 10px; height: 10px;
      background: var(--green);
      border-radius: 50%;
      display: inline-block;
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }
    .nav-links a {
      font-size: 14px;
      font-weight: 600;
      color: var(--text-dark);
      text-decoration: none;
      transition: color 0.2s;
    }
    .nav-links a:hover { color: var(--purple); }
    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      font-family: var(--font);
      font-weight: 700;
      border: none;
      cursor: pointer;
      transition: all 0.2s;
      text-decoration: none;
      white-space: nowrap;
    }
    .btn-sm { padding: 9px 20px; font-size: 13px; border-radius: var(--radius-full); }
    .btn-md { padding: 14px 28px; font-size: 15px; border-radius: var(--radius-full); }
    .btn-lg { padding: 16px 36px; font-size: 16px; border-radius: var(--radius-full); }
    .btn-ghost {
      background: transparent;
      color: var(--text-dark);
    }
    .btn-ghost:hover { color: var(--purple); }
    .btn-outline {
      background: transparent;
      border: 2px solid var(--black);
      color: var(--black);
    }
    .btn-outline:hover { background: var(--black); color: var(--white); }
    .btn-primary {
      background: var(--black);
      color: var(--white);
    }
    .btn-primary:hover { background: #222; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(0,0,0,0.18); }
    .btn-green {
      background: var(--green);
      color: var(--black);
    }
    .btn-green:hover { background: #3ECB88; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(85,218,155,0.35); }
    .btn-purple {
      background: var(--purple);
      color: var(--white);
    }
    .btn-purple:hover { background: #4516A8; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(86,32,193,0.35); }

    /* ─── HERO ─── */
    .hero {
      background: var(--black);
      color: var(--white);
      padding: 80px 40px 60px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -120px; left: -120px;
      width: 500px; height: 500px;
      background: radial-gradient(circle, rgba(86,32,193,0.35) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -80px; right: -80px;
      width: 400px; height: 400px;
      background: radial-gradient(circle, rgba(85,218,155,0.2) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(85,218,155,0.15);
      border: 1px solid rgba(85,218,155,0.35);
      color: var(--green);
      font-size: 13px;
      font-weight: 700;
      padding: 6px 16px;
      border-radius: var(--radius-full);
      margin-bottom: 28px;
      letter-spacing: 0.3px;
    }
    .hero-title {
      font-size: clamp(36px, 6vw, 72px);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -2px;
      max-width: 760px;
      margin: 0 auto 20px;
    }
    .hero-title em {
      font-style: normal;
      color: var(--green);
    }
    .hero-subtitle {
      font-size: 20px;
      font-weight: 500;
      color: rgba(255,255,255,0.65);
      margin-bottom: 40px;
    }
    .hero-cta-group {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      margin-bottom: 16px;
    }
    .hero-cta-group .btn {
      width: 100%;
      max-width: 380px;
    }
    .btn-google {
      background: var(--white);
      color: var(--black);
      font-size: 15px;
    }
    .btn-google:hover { background: #F0F0F0; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(255,255,255,0.18); }
    .btn-email {
      background: transparent;
      border: 2px solid rgba(255,255,255,0.35);
      color: var(--white);
      font-size: 15px;
    }
    .btn-email:hover { border-color: var(--white); background: rgba(255,255,255,0.06); }
    .hero-legal {
      font-size: 11px;
      color: rgba(255,255,255,0.35);
      max-width: 420px;
      margin: 0 auto 44px;
      line-height: 1.6;
    }
    .hero-legal a { color: rgba(255,255,255,0.5); }
    .hero-categories {
      display: flex;
      gap: 10px;
      justify-content: center;
      flex-wrap: wrap;
      padding-top: 8px;
    }
    .category-pill {
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.15);
      color: rgba(255,255,255,0.8);
      font-size: 13px;
      font-weight: 600;
      padding: 8px 18px;
      border-radius: var(--radius-full);
      cursor: pointer;
      transition: all 0.2s;
      text-decoration: none;
    }
    .category-pill:hover {
      background: var(--green);
      border-color: var(--green);
      color: var(--black);
      transform: translateY(-2px);
    }

    /* ─── SECTION SHARED ─── */
    section { padding: 88px 40px; }
    .section-label {
      font-size: 12px;
      font-weight: 800;
      letter-spacing: 2px;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(28px, 4vw, 46px);
      font-weight: 800;
      letter-spacing: -1.5px;
      line-height: 1.1;
      color: var(--black);
      margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 17px;
      color: var(--text-muted);
      max-width: 560px;
      line-height: 1.65;
    }
    .section-header { margin-bottom: 52px; }

    /* ─── FEATURES ─── */
    .features { background: var(--off-white); }
    .features-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }
    .features-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 32px;
    }
    .feature-item {
      display: flex;
      gap: 18px;
      align-items: flex-start;
    }
    .feature-icon {
      width: 48px;
      height: 48px;
      border-radius: var(--radius-md);
      background: var(--black);
      color: var(--green);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 22px;
    }
    .feature-text h3 {
      font-size: 18px;
      font-weight: 800;
      letter-spacing: -0.3px;
      margin-bottom: 4px;
      color: var(--black);
    }
    .feature-text p {
      font-size: 14px;
      color: var(--text-muted);
      line-height: 1.6;
    }
    .features-visual {
      background: var(--black);
      border-radius: var(--radius-lg);
      padding: 40px;
      display: flex;
      flex-direction: column;
      gap: 20px;
      box-shadow: 0 32px 80px rgba(0,0,0,0.2);
    }
    .feat-card {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-md);
      padding: 20px;
      display: flex;
      align-items: center;
      gap: 14px;
    }
    .feat-card-icon {
      width: 44px; height: 44px;
      border-radius: 10px;
      background: var(--green);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      flex-shrink: 0;
    }
    .feat-card-text strong {
      display: block;
      font-size: 15px;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 2px;
    }
    .feat-card-text span {
      font-size: 12px;
      color: rgba(255,255,255,0.45);
    }
    .feat-card-badge {
      margin-left: auto;
      font-size: 11px;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: var(--radius-full);
    }
    .badge-green { background: rgba(85,218,155,0.2); color: var(--green); }
    .badge-purple { background: rgba(86,32,193,0.3); color: #A07BFF; }

    /* ─── STATS ─── */
    .stats {
      background: var(--black);
      color: var(--white);
      padding: 72px 40px;
    }
    .stats-inner {
      max-width: 1100px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      text-align: center;
    }
    .stat-card {
      padding: 36px 20px;
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-lg);
      background: rgba(255,255,255,0.03);
      transition: border-color 0.2s, transform 0.2s;
    }
    .stat-card:hover { border-color: var(--green); transform: translateY(-4px); }
    .stat-number {
      font-size: clamp(42px, 5vw, 64px);
      font-weight: 800;
      letter-spacing: -3px;
      color: var(--green);
      line-height: 1;
      margin-bottom: 10px;
    }
    .stat-label {
      font-size: 14px;
      font-weight: 600;
      color: rgba(255,255,255,0.5);
      letter-spacing: 0.5px;
    }

    /* ─── COURSES ─── */
    .courses { background: var(--white); }
    .courses-inner { max-width: 1200px; margin: 0 auto; }
    .tabs-scroll {
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding-bottom: 4px;
      margin-bottom: 40px;
      scrollbar-width: none;
    }
    .tabs-scroll::-webkit-scrollbar { display: none; }
    .tab-btn {
      flex-shrink: 0;
      padding: 9px 20px;
      border-radius: var(--radius-full);
      font-family: var(--font);
      font-size: 13px;
      font-weight: 700;
      cursor: pointer;
      border: 2px solid var(--border);
      background: transparent;
      color: var(--text-muted);
      transition: all 0.2s;
    }
    .tab-btn:hover { border-color: var(--black); color: var(--black); }
    .tab-btn.active {
      background: var(--black);
      border-color: var(--black);
      color: var(--white);
    }
    .courses-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 22px;
    }
    .course-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--border);
      background: var(--card-bg);
      cursor: pointer;
      transition: box-shadow 0.25s, transform 0.25s;
    }
    .course-card:hover { box-shadow: 0 12px 40px rgba(0,0,0,0.1); transform: translateY(-4px); }
    .course-thumb {
      width: 100%;
      aspect-ratio: 16/9;
      background: var(--light-gray);
      position: relative;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .course-thumb-bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 52px;
    }
    .course-thumb-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to bottom, transparent 40%, rgba(0,0,0,0.6) 100%);
    }
    .course-duration {
      position: absolute;
      bottom: 10px; right: 10px;
      background: rgba(0,0,0,0.75);
      color: var(--white);
      font-size: 11px;
      font-weight: 700;
      padding: 3px 8px;
      border-radius: 5px;
    }
    .course-info { padding: 16px; }
    .course-title {
      font-size: 13.5px;
      font-weight: 700;
      line-height: 1.4;
      color: var(--text-dark);
      margin-bottom: 8px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .course-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .course-instructor {
      font-size: 12px;
      color: var(--text-muted);
      font-weight: 600;
    }
    .course-students {
      font-size: 11px;
      color: var(--text-muted);
      display: flex;
      align-items: center;
      gap: 4px;
    }

    /* ─── CREATIVE FEED ─── */
    .feed { background: var(--black); color: var(--white); }
    .feed-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .feed-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }
    .feed-post {
      border-radius: var(--radius-md);
      overflow: hidden;
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      position: relative;
    }
    .feed-post:nth-child(1) { background: linear-gradient(135deg, #5620C1, #9B59FF); }
    .feed-post:nth-child(2) { background: linear-gradient(135deg, #FF6B35, #FFB347); margin-top: 24px; }
    .feed-post:nth-child(3) { background: linear-gradient(135deg, #55DA9B, #1DBFB8); margin-top: -24px; }
    .feed-post:nth-child(4) { background: linear-gradient(135deg, #FF4F7B, #FF9E80); }
    .feed-post-like {
      position: absolute;
      bottom: 10px; right: 10px;
      background: rgba(255,255,255,0.2);
      border-radius: var(--radius-full);
      padding: 5px 10px;
      font-size: 11px;
      font-weight: 700;
      color: var(--white);
    }
    .feed-items { display: flex; flex-direction: column; gap: 36px; }
    .feed-item { display: flex; gap: 20px; align-items: flex-start; }
    .feed-item-icon {
      width: 52px; height: 52px;
      border-radius: var(--radius-md);
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.12);
      display: flex; align-items: center; justify-content: center;
      font-size: 22px;
      flex-shrink: 0;
    }
    .feed-item h3 {
      font-size: 18px;
      font-weight: 800;
      letter-spacing: -0.3px;
      margin-bottom: 6px;
      color: var(--white);
    }
    .feed-item p {
      font-size: 14px;
      color: rgba(255,255,255,0.5);
      line-height: 1.65;
    }

    /* ─── TEACHERS ─── */
    .teachers { background: var(--off-white); overflow: hidden; }
    .teachers-inner { max-width: 1200px; margin: 0 auto; }
    .teachers-carousel {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      padding-bottom: 12px;
      scrollbar-width: none;
      cursor: grab;
      user-select: none;
    }
    .teachers-carousel:active { cursor: grabbing; }
    .teachers-carousel::-webkit-scrollbar { display: none; }
    .teacher-card {
      flex-shrink: 0;
      width: 220px;
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      text-align: center;
      transition: box-shadow 0.25s, transform 0.25s;
      cursor: pointer;
    }
    .teacher-card:hover { box-shadow: 0 12px 40px rgba(0,0,0,0.1); transform: translateY(-4px); }
    .teacher-avatar {
      width: 100%;
      height: 200px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 64px;
      position: relative;
    }
    .teacher-avatar-inner {
      width: 90px; height: 90px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 36px;
      border: 3px solid var(--white);
      box-shadow: 0 4px 20px rgba(0,0,0,0.15);
    }
    .teacher-info { padding: 16px; }
    .teacher-name {
      font-size: 15px;
      font-weight: 800;
      color: var(--black);
      margin-bottom: 4px;
    }
    .teacher-specialty {
      font-size: 12px;
      color: var(--text-muted);
      font-weight: 600;
    }
    .teachers-nav {
      display: flex;
      gap: 10px;
      margin-top: 28px;
    }
    .nav-arrow {
      width: 44px; height: 44px;
      border-radius: 50%;
      background: var(--black);
      border: none;
      color: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      font-size: 18px;
      transition: background 0.2s, transform 0.2s;
    }
    .nav-arrow:hover { background: var(--purple); transform: scale(1.08); }

    /* ─── TESTIMONIALS ─── */
    .testimonials { background: var(--white); }
    .testimonials-inner { max-width: 1200px; margin: 0 auto; }
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 22px;
    }
    .testimonial-card {
      background: var(--off-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 32px;
      transition: box-shadow 0.2s;
    }
    .testimonial-card:hover { box-shadow: 0 8px 30px rgba(0,0,0,0.07); }
    .testimonial-quote {
      font-size: 24px;
      color: var(--green);
      margin-bottom: 16px;
      font-family: Georgia, serif;
      line-height: 1;
    }
    .testimonial-text {
      font-size: 16px;
      line-height: 1.7;
      color: var(--text-dark);
      margin-bottom: 24px;
      font-weight: 500;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .testimonial-avatar {
      width: 44px; height: 44px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      font-weight: 800;
      color: var(--white);
      flex-shrink: 0;
    }
    .testimonial-name {
      font-size: 14px;
      font-weight: 800;
      color: var(--black);
    }
    .testimonial-stars {
      font-size: 11px;
      color: #FFB800;
      margin-top: 2px;
    }

    /* ─── TEAMS ─── */
    .teams {
      background: linear-gradient(135deg, #5620C1 0%, #3A0E9C 100%);
      color: var(--white);
      padding: 88px 40px;
    }
    .teams-inner {
      max-width: 1100px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .teams .section-label { color: var(--green); }
    .teams .section-title { color: var(--white); }
    .teams .section-subtitle { color: rgba(255,255,255,0.65); max-width: 460px; }
    .teams-visual {
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: var(--radius-lg);
      padding: 36px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }
    .team-row {
      display: flex;
      align-items: center;
      gap: 12px;
      background: rgba(255,255,255,0.07);
      border-radius: var(--radius-md);
      padding: 14px;
    }
    .team-avatar-group { display: flex; }
    .team-mini-avatar {
      width: 32px; height: 32px;
      border-radius: 50%;
      border: 2px solid rgba(255,255,255,0.2);
      margin-left: -8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
    }
    .team-mini-avatar:first-child { margin-left: 0; }
    .team-row-text strong {
      display: block;
      font-size: 13px;
      font-weight: 700;
      color: var(--white);
    }
    .team-row-text span { font-size: 11px; color: rgba(255,255,255,0.45); }
    .team-progress {
      margin-left: auto;
      background: rgba(255,255,255,0.1);
      border-radius: var(--radius-full);
      height: 6px;
      width: 80px;
      overflow: hidden;
    }
    .team-progress-fill {
      height: 100%;
      background: var(--green);
      border-radius: var(--radius-full);
    }

    /* ─── FAQ ─── */
    .faq { background: var(--off-white); }
    .faq-inner {
      max-width: 760px;
      margin: 0 auto;
    }
    .faq-item {
      border-bottom: 1px solid var(--mid-gray);
      overflow: hidden;
    }
    .faq-item:first-child { border-top: 1px solid var(--mid-gray); }
    .faq-question {
      width: 100%;
      text-align: left;
      background: transparent;
      border: none;
      padding: 24px 0;
      font-family: var(--font);
      font-size: 17px;
      font-weight: 700;
      color: var(--black);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      transition: color 0.2s;
    }
    .faq-question:hover { color: var(--purple); }
    .faq-question.open { color: var(--purple); }
    .faq-chevron {
      width: 28px; height: 28px;
      border-radius: 50%;
      background: var(--mid-gray);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      transition: transform 0.3s, background 0.2s;
      font-size: 14px;
    }
    .faq-question.open .faq-chevron {
      transform: rotate(180deg);
      background: var(--purple);
      color: var(--white);
    }
    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.35s ease, padding 0.25s ease;
    }
    .faq-answer.open { max-height: 300px; padding-bottom: 24px; }
    .faq-answer p {
      font-size: 15px;
      line-height: 1.75;
      color: var(--text-muted);
    }
    .faq-cta {
      text-align: center;
      margin-top: 52px;
    }
    .faq-cta p { font-size: 16px; color: var(--text-muted); margin-bottom: 20px; }

    /* ─── FOOTER ─── */
    footer {
      background: var(--black);
      color: var(--white);
      padding: 72px 40px 40px;
    }
    .footer-inner { max-width: 1200px; margin: 0 auto; }
    .footer-top {
      display: grid;
      grid-template-columns: 220px repeat(4, 1fr);
      gap: 40px;
      padding-bottom: 52px;
      border-bottom: 1px solid rgba(255,255,255,0.08);
    }
    .footer-brand { }
    .footer-brand .nav-logo {
      color: var(--white);
      font-size: 20px;
      margin-bottom: 14px;
      display: inline-flex;
    }
    .footer-brand p {
      font-size: 13px;
      color: rgba(255,255,255,0.45);
      line-height: 1.65;
      margin-bottom: 20px;
    }
    .footer-col h4 {
