      align-items: center;
      justify-content: center;
      text-decoration: none;
      font-size: 15px;
      transition: background 0.2s, border-color 0.2s;
    }
    .social-link:hover { background: var(--green); border-color: var(--green); }

    /* ─── MODAL ─── */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.6);
      backdrop-filter: blur(6px);
      z-index: 1000;
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.25s;
    }
    .modal-overlay.open { opacity: 1; pointer-events: all; }
    .modal {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 40px;
      width: 100%;
      max-width: 440px;
      margin: 20px;
      transform: translateY(16px);
      transition: transform 0.3s;
      position: relative;
    }
    .modal-overlay.open .modal { transform: translateY(0); }
    .modal-close {
      position: absolute;
      top: 16px; right: 16px;
      width: 32px; height: 32px;
      border-radius: 50%;
      background: var(--light-gray);
      border: none;
      cursor: pointer;
      font-size: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s;
    }
    .modal-close:hover { background: var(--mid-gray); }
    .modal-logo {
      font-size: 20px;
      font-weight: 800;
      letter-spacing: -0.5px;
      color: var(--black);
      margin-bottom: 6px;
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .modal h2 {
      font-size: 24px;
      font-weight: 800;
      letter-spacing: -0.5px;
      margin-bottom: 8px;
    }
    .modal p {
      font-size: 14px;
      color: var(--text-muted);
      margin-bottom: 24px;
      line-height: 1.55;
    }
    .modal-form { display: flex; flex-direction: column; gap: 12px; }
    .modal-input {
      width: 100%;
      padding: 13px 16px;
      border: 2px solid var(--border);
      border-radius: var(--radius-md);
      font-family: var(--font);
      font-size: 14px;
      color: var(--text-dark);
      outline: none;
      transition: border-color 0.2s;
    }
    .modal-input:focus { border-color: var(--purple); }
    .modal-legal {
      font-size: 11px;
      color: var(--text-muted);
      line-height: 1.6;
      text-align: center;
      margin-top: 4px;
    }
    .modal-legal a { color: var(--purple); }
    .modal-divider {
      display: flex;
      align-items: center;
      gap: 12px;
      margin: 4px 0;
    }
    .modal-divider-line { flex: 1; height: 1px; background: var(--border); }
    .modal-divider span { font-size: 12px; color: var(--text-muted); font-weight: 600; }

    /* ─── ANIMATIONS ─── */
    @keyframes fadeUp {
      from { opacity: 0; transform: translateY(24px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    .hero-badge { animation: fadeUp 0.5s ease both; }
    .hero-title { animation: fadeUp 0.55s 0.1s ease both; }
    .hero-subtitle { animation: fadeUp 0.55s 0.18s ease both; }
    .hero-cta-group { animation: fadeUp 0.55s 0.26s ease both; }
    .hero-legal { animation: fadeUp 0.55s 0.32s ease both; }
    .hero-categories { animation: fadeUp 0.55s 0.38s ease both; }

    /* ─── RESPONSIVE ─── */
    @media (max-width: 1100px) {
      .courses-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-top { grid-template-columns: 1fr 1fr; gap: 32px; }
    }
    @media (max-width: 900px) {
      .features-inner { grid-template-columns: 1fr; }
      .features-visual { display: none; }
      .stats-inner { grid-template-columns: repeat(2, 1fr); }
      .courses-grid { grid-template-columns: repeat(2, 1fr); }
      .feed-inner { grid-template-columns: 1fr; }
      .teams-inner { grid-template-columns: 1fr; }
      .testimonials-grid { grid-template-columns: 1fr; }
    }
    @media (max-width: 768px) {
      nav { padding: 0 20px; }
      .nav-links { display: none; }
      section { padding: 60px 20px; }
      .hero { padding: 60px 20px 48px; }
      .hero-title { letter-spacing: -1px; }
      .hero-subtitle { font-size: 16px; }
      .courses-grid { grid-template-columns: 1fr 1fr; }
